const PREPASS_ORDER = -10;
/**
 * The sprite depth prepass + EQUAL-depth lit pass (trees/Drawing.md#depth) is opt-in (`?treeprepass=1`): it needs the
 * prepass and the lit program to compute bit-identical depths, which WebGL cannot guarantee across drivers even with
 * `invariant gl_Position` (an EQUAL miss leaves a pixel unshaded). By default sprites draw once, alpha-tested, with
 * the normal depth test, writing depth like every other tree level. Debug view 5 shows any EQUAL misses in magenta.
 */
export const SPRITE_PREPASS =
  typeof location !== 'undefined' && new URLSearchParams(location.search).get('treeprepass') === '1';
