export interface BenchRun {
  trees: boolean;
  frames: number;
  /** Frame time incl. GPU (each frame ends with gl.finish(), so vsync does not cap it), ms. */
  avgMs: number;
  /** 1 % low: the 99th percentile frame time. */
  low1Ms: number;
  worstMs: number;
  /** Tree main + shadow pass GPU ms per frame (timer queries; NaN = no timer). */
  treeGpuMs: number;
