  frameMs: 1.0,
  low1Ms: 1.0,
  /** Level selection + fade updates per frame (ms). */
  selectMs: 0.1,
  /** Added to the stage load (ms). */
  loadMs: 500,
};

export interface BudgetResult {
  pass: boolean;
